export class SlotRegistry<T> {
  private entries: Map<string, T> = new Map<string, T>();

  set(name: string, value: T): void {
    if (typeof name !== "string" || name.trim().length === 0) {
      throw new TypeError("name must be non-blank");
    }
    this.entries.set(name, value);
  }

  get(name: string): T | undefined {
    return this.entries.get(name);
  }

  detachAll(): Map<string, T> {
    const detached = new Map<string, T>(this.entries);
    this.entries.clear();
    return detached;
  }

  attachAll(entries: ReadonlyMap<string, T>): void {
    this.entries = entries as Map<string, T>;
  }

  snapshot(): Map<string, T> {
    return new Map<string, T>(this.entries);
  }
}
```

