import { SlotRegistry } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectTypeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof TypeError) return; throw new Error(`${message}: wrong error type`); }
  throw new Error(`${message}: did not throw`);
}

const registry = new SlotRegistry<{ value: number }>();
const firstValue = { value: 1 };
const replacement = { value: 2 };
registry.set(' slot ', firstValue);
equal(registry.get(' slot '), firstValue, 'set and get preserve exact name and value reference');
equal(registry.get('slot'), undefined, 'lookup is exact');
registry.set(' slot ', replacement);
equal(registry.get(' slot '), replacement, 'set replaces existing name');
expectTypeError(() => registry.set(' \n ', firstValue), 'blank slot name');
expectTypeError(() => registry.set(3 as unknown as string, firstValue), 'non-string slot name');

registry.set('second', firstValue);
const snapshot = registry.snapshot();
equal(snapshot.get(' slot '), replacement, 'snapshot contains current entry');
snapshot.delete(' slot ');
snapshot.set('external', { value: 9 });
equal(registry.get(' slot '), replacement, 'snapshot deletion does not affect registry');
equal(registry.get('external'), undefined, 'snapshot addition does not affect registry');

const detached = registry.detachAll();
equal(detached.size, 2, 'detach returns all entries');
equal(detached.get(' slot '), replacement, 'detached values retain references');
equal(registry.get(' slot '), undefined, 'detach empties registry');
equal(registry.snapshot().size, 0, 'registry is empty after detach');
detached.set('after-detach', firstValue);
equal(registry.get('after-detach'), undefined, 'detached map does not alias registry');

const supplied = new Map<string, { value: number }>();
supplied.set('z', firstValue);
supplied.set('a', replacement);
registry.set('old', { value: 0 });
registry.attachAll(supplied);
equal(registry.get('old'), undefined, 'attach replaces old entries');
equal(registry.get('z'), firstValue, 'attach keeps value references');
assert(Array.from(registry.snapshot().keys()).join(',') === 'z,a', 'attach preserves supplied key order');
supplied.delete('z');
supplied.set('later', { value: 3 });
equal(registry.get('z'), firstValue, 'caller map deletion does not affect registry');
equal(registry.get('later'), undefined, 'caller map addition does not affect registry');
firstValue.value = 7;
equal(registry.get('z')?.value, 7, 'values are intentionally retained by reference');

registry.attachAll(new Map());
equal(registry.snapshot().size, 0, 'empty map attachment is valid and clears entries');

